int __cdecl f_before(int *p, int n, int seed)
{
    int i;
    int x = seed;
    int y = 3;
    int z = 5;
    for (i = 0; i < n; ++i) {
        x += p[i] * y;
        y += z;
        z = (z * 3) ^ i;
    }
    return (x + y + z) + (seed + 1);
}
